def _memory_decorator(memory, key_func):
    def decorator(func):
        def key(*a, **kw):
            return key_func(*a, **kw) if key_func else (a + tuple(sorted(kw.items())) if kw else a)
        @wraps(func)
        def wrapper(*a, **kw):
            k = key(*a, **kw)
            try:
                return memory[k]
            except KeyError:
                try:
                    v = func(*a, **kw)
                except SkipMemory as e:
                    return e.args[0] if e.args else None
                memory[k] = v
                return v
        def invalidate(*a, **kw):
            memory.pop(key(*a, **kw), None)
        wrapper.invalidate = invalidate
        def invalidate_all():
            memory.clear()
        wrapper.invalidate_all = invalidate_all
        wrapper.memory = memory
        return wrapper
    return decorator
```

