def get_spec(func, _cache={}):
    func = getattr(func, '__original__', None) or unwrap(func)
    try:
        return _cache[func]
    except (KeyError, TypeError):
        mod = getattr(func, '__module__', None)
        if mod in STD_MODULES or mod in ARGS and func.__name__ in ARGS[mod]:
            req, _, opt = ARGS[mod].get(func.__name__, '*').partition('-')
            req_names = re.findall(r'\w+|\*', req)
            return _cache.setdefault(func, Spec(len(req_names) + len(opt), set(), len(req_names), set(req_names), False))
        if isinstance(func, type):
            obj = getattr(func.__init__, '__objclass__', None)
            if obj and obj is not func:
                return get_spec(obj)
            s = get_spec(func.__init__)
            self = func.__init__.__code__.co_varnames[0]
            return s._replace(max_n=s.max_n-1, names=s.names-{self}, req_n=s.req_n-1, req_names=s.req_names-{self})
        if hasattr(func, '__code__'):
            return _code_to_spec(func)
        try:
            sig = signature(func)
        except (ValueError, TypeError):
            raise ValueError('Unable to introspect %s() arguments' % (getattr(func, '__qualname__', None) or getattr(func, '__name__', func)))
        return _cache.setdefault(func, _sig_to_spec(sig))
```

